/* ---------------- 建模小工具 ---------------- */
const MATS = {};
function mat(color, rough = 0.85, metal = 0.05) {
  const k = color + '_' + rough + '_' + metal;
  return MATS[k] || (MATS[k] = new THREE.MeshStandardMaterial({ color, roughness: rough, metalness: metal }));
}
function bx(w, h, d, color, x, y, z, parent = scene, ry = 0) {
  const m = new THREE.Mesh(new THREE.BoxGeometry(w, h, d), mat(color));
  m.position.set(x, y, z); m.rotation.y = ry;
  m.castShadow = true; m.receiveShadow = true;
  parent.add(m); return m;
}
function cyl(rt, rb, h, color, x, y, z, parent = scene, seg = 12) {
  const m = new THREE.Mesh(new THREE.CylinderGeometry(rt, rb, h, seg), mat(color));
  m.position.set(x, y, z); m.castShadow = true; m.receiveShadow = true;
  parent.add(m); return m;
}
function sph(r, color, x, y, z, parent = scene, ws = 14, hs = 10) {
  const m = new THREE.Mesh(new THREE.SphereGeometry(r, ws, hs), mat(color));
  m.position.set(x, y, z); m.castShadow = true; m.receiveShadow = true;
  parent.add(m); return m;
}
function statusDot(x, y, z, r = 0.35) {
  const m = new THREE.Mesh(new THREE.SphereGeometry(r, 8, 6),
    new THREE.MeshStandardMaterial({ color: 0x8d95a0, emissive: 0x8d95a0, emissiveIntensity: 0.9 }));
  m.position.set(x, y, z); scene.add(m); return m;
}
function setDot(m, color) { m.material.color.setHex(color); m.material.emissive.setHex(color); }
function tubeAlong(pts, radius, color, op = 1) {
  const curve = new THREE.CatmullRomCurve3(pts.map(p => new THREE.Vector3(...p)));
  const m = new THREE.Mesh(new THREE.TubeGeometry(curve, Math.max(8, pts.length * 4), radius, 6, false),
    new THREE.MeshStandardMaterial({ color, roughness: 0.6, metalness: 0.3, transparent: op < 1, opacity: op }));
  scene.add(m); return m;
}
const WINMATS = [];                                    // 夜间发光窗材质
function winMat() {
  const m = new THREE.MeshStandardMaterial({ color: 0x2c3640, emissive: 0xe8c98a, emissiveIntensity: 0 });
  WINMATS.push(m); return m;
}
