/* ---------------- 边线管线与粒子点 ---------------- */
for (const e of EDGES) {
  /* 管线与粒子共用同一介质色（桥接层按 电/氢/氨/数据/外购/核电 写入
   * tubeColor）：避免出现"管是灰的、粒子是彩的"的语义断裂。
   * 数据流用更细的线径与更低的透明度，与电力流在视觉上区分开。 */
  if (e.dataFlow) tubeAlong(e.pts, 0.045, e.tubeColor || 0x9BCEF5, 0.55);
  else if (e.pipe) tubeAlong(e.pts, 0.16, e.tubeColor || 0x3a4650);
  else tubeAlong(e.pts, 0.07, e.tubeColor || 0x46525e, 0.9);
  const g = new THREE.BufferGeometry();
  g.setAttribute('position', new THREE.BufferAttribute(new Float32Array(PART_CAP * 3), 3));
  const pm = new THREE.PointsMaterial({ color: e.color || 0xdfa45c, size: e.dataFlow ? 0.34 : 0.55,
    transparent: true, opacity: 0.95, blending: THREE.AdditiveBlending, depthWrite: false });
  e.points = new THREE.Points(g, pm); e.points.frustumCulled = false;
  scene.add(e.points);
}
/* v18：风/光/SMR 架空馈线杆塔（与 EDGES.poles 一一对应，粒子沿导线走） */
for (const e of EDGES) {
  if (!e.poles) continue;
  for (const [px2, pz2] of e.poles) {
    cyl(0.14, 0.22, 9.6, 0x8b959e, px2, 4.8, pz2, scene, 6);
    bx(2.8, 0.16, 0.16, 0x8b959e, px2, 8.0, pz2);
  }
}
function drawParticles() {
  for (const e of EDGES) {
    const a = e.points.geometry.attributes.position;
    let n = 0;
    for (const pt of e.parts) {
      const p = edgePoint(e, pt.d);
      a.array[n * 3] = p[0]; a.array[n * 3 + 1] = p[1]; a.array[n * 3 + 2] = p[2];
      n++;
    }
    for (let i = n; i < PART_CAP; i++) { a.array[i * 3 + 1] = -50; }
    a.needsUpdate = true;
    e.points.geometry.setDrawRange(0, Math.max(1, n));
  }
}

