/* logo 共用加载器：白底透明化后回调 canvas */
function loadLogoCanvas(cb) {
  const img = new Image();
  img.onload = () => {
    const c = document.createElement('canvas');
    c.width = img.width; c.height = img.height;
    const g = c.getContext('2d');
    g.drawImage(img, 0, 0);
    const d = g.getImageData(0, 0, c.width, c.height);
    const a = d.data;
    for (let i = 0; i < a.length; i += 4) {
      if (a[i] > 235 && a[i + 1] > 235 && a[i + 2] > 235) a[i + 3] = 0;   // 白底→透明
    }
    g.putImageData(d, 0, 0);
    cb(c);
  };
  img.src = 'data:image/svg+xml;base64,';
}
function logoTexture() {
  const c0 = document.createElement('canvas'); c0.width = c0.height = 2;
  const tex = new THREE.CanvasTexture(c0);
  tex.encoding = THREE.sRGBEncoding;
  loadLogoCanvas(c => { tex.image = c; tex.needsUpdate = true; });
  return tex;
}
/* v18：浅灰标牌贴图 = 灰底 + logo + “零碳园区” + 副标题 */
function signTexture() {
  const c = document.createElement('canvas');
  c.width = 1600; c.height = 360;
  const tex = new THREE.CanvasTexture(c);
  tex.encoding = THREE.sRGBEncoding;
  tex.anisotropy = 4;
  function draw(logoC) {
    const g = c.getContext('2d');
    g.fillStyle = '#c8ced4';                             // 浅灰牌面
    g.fillRect(0, 0, 1600, 360);
    g.strokeStyle = 'rgba(28,35,43,.28)'; g.lineWidth = 6;
    g.strokeRect(8, 8, 1584, 344);
    if (logoC) g.drawImage(logoC, 48, 66, 750, 230);
    g.fillStyle = '#1c232b';
    g.font = 'bold 64px "Microsoft YaHei", "PingFang SC", sans-serif';
    g.textBaseline = 'middle';
    g.fillText('多园区共享综合能源系统', 856, 152, 700);
    g.fillStyle = '#3a4650';
    g.font = '44px "Microsoft YaHei", "PingFang SC", sans-serif';
    g.fillText('西比里 能源 xibili energy', 862, 266);
    tex.needsUpdate = true;
  }
  draw(null);                                            // 先灰底兜底
  loadLogoCanvas(logoC => draw(logoC));
  return tex;
}
const logoTex = logoTexture();
/* v19：旗帜专用贴图 = 白色旗面底 + 居中 logo（logo 透明区不再漏底） */
function flagTexture() {
  const c = document.createElement('canvas');
  c.width = 1292; c.height = 400;                      // ≈旗面 4.2×1.3 比例
  const tex = new THREE.CanvasTexture(c);
  tex.encoding = THREE.sRGBEncoding;
  tex.anisotropy = 4;
  function draw(logoC) {
    const g = c.getContext('2d');
    g.fillStyle = '#faf8f3';                           // 白布底色
    g.fillRect(0, 0, 1292, 400);
    if (logoC) {
      const lh = 244, lw = lh * (logoC.width / logoC.height);
      g.drawImage(logoC, (1292 - lw) / 2, (400 - lh) / 2, lw, lh);
    }
    tex.needsUpdate = true;
  }
  draw(null);                                          // 先白布兜底
  loadLogoCanvas(logoC => draw(logoC));
  return tex;
}
