function tree(x, z, s, round) {
  cyl(0.1 * s, 0.16 * s, 2.0 * s, 0x5a4a38, x, 1.0 * s, z, scene, 6);
  if (round) {
    const cn = sph(1.05 * s, 0x557a4a, x, 2.6 * s, z, scene, 8, 6);
    cn.scale.y = 0.85;
  } else {
    const cn = new THREE.Mesh(new THREE.ConeGeometry(0.95 * s, 3.2 * s, 7), mat(0x4a6a44, 0.95, 0));
    cn.position.set(x, 3.6 * s, z); cn.castShadow = true; scene.add(cn);
  }
}
