/* v1.0.2：原本在这里动态注入左上角的「地区 · 昼夜」文字与日月弧 canvas。
 * 前者压在顶栏渐变层下方、又被每 0.25 秒重写一次；后者被 premium 层每帧
 * 重绘 —— 两者合起来就是"顶部一直在闪"。已整体移除，同样的信息改由底部
 * 信息流 #ticker 滚动播报（见 overlay.html / premium.js 的 updateTicker）。 */
/* ---------------- 动画钩子 ---------------- */
TICKERS.push((tNow, dtR) => {                          // 风机旋转
  for (let i = 0; i < rotors.length; i++) {
    bladeAng[i] += dtR * (0.4 + S.turbP[i] * 0.9);
    rotors[i].rotation.z = bladeAng[i];
  }
  pvPanelM.color.setHex(S.irradi > 0.02 ? 0x35648a : 0x22384c);
  pvPanelM.metalness = 0.3 + S.irradi * 0.3;
});
TICKERS.push(() => {                                   // SMR 状态灯
  const running = S.smrGear > 0, steady = Math.abs(S.smr - S.smrGear * K.SMR_CAP / 2) < 0.6;
  setDot(smrDot, !running ? 0xcc6f5f : (steady ? 0x84b07c : 0xd99a5b));
  setDot(gensetDot, S.gensetOn ? (S.gensetMW > 45 ? 0x84b07c : 0xd99a5b) : 0x8d95a0);
  setDot(nh3Dot, S.nh3Load > 0.8 ? 0x84b07c : (S.nh3Load > 0.02 ? 0xd99a5b : 0x8d95a0));
});
TICKERS.push(() => {                                   // 储能 SOC 条 / PEM 辉光 / 锌槽
  socBar.scale.x = Math.max(0.02, S.soc / 100);
  socBar.position.x = 28 - 2.8 * (1 - S.soc / 100);
  socBar.material.color.setHex(S.soc < 15 ? 0xcc6f5f : (S.soc > 90 ? 0xd99a5b : 0x84b07c));
  socBar.material.emissive.setHex(S.soc < 15 ? 0xcc6f5f : (S.soc > 90 ? 0xd99a5b : 0x84b07c));
  for (const m of pemGlow) m.emissiveIntensity = S.h2P > 0.1 ? 0.3 + 0.7 * (S.h2P / K.H2_CAP) : 0;
  const zl = S.metal / K.METAL_CAP;
  for (const m of zincCellM) m.emissiveIntensity = 0.05 + zl * 0.5;
  const lv = clamp(S.h2Kg / K.H2_TANK, 0.02, 1);
  h2Liquid.scale.setScalar(Math.cbrt(lv));
});
TICKERS.push((tNow) => {                               // 重卡 / 工厂动画（慢速）
  // Retired occupancy blocks never encode charging.
  for(const t of truckPool)t.visible=false;
  const spd = S.factory / K.FACTORY_CAP;
  /* v19：传送带/机械臂大幅降速（按真实时间，不再随观感过快） */
  for (let i = 0; i < beltBoxes.length; i++)
    beltBoxes[i].position.x = 162 + ((tNow * (0.9 + 3.6 * spd) + i * 48) % 90) / 10;
  const a1 = -0.6 + Math.sin(tNow * (0.06 + spd * 0.20)) * 0.4 * (0.2 + spd);
  const a2 = 0.5 + Math.cos(tNow * (0.08 + spd * 0.20)) * 0.35 * (0.2 + spd);
  armG.rotation.z = a1; armJ.rotation.z = a2;
});
TICKERS.push((tNow) => {                               // 机柜指示灯 / 消防警灯 / 旗帜飘扬
  for (let i = 0; i < rackLEDs.length; i++) {
    rackLEDs[i].emissiveIntensity = Math.sin(tNow * (2.1 + (i % 5) * 0.7) + i * 1.7) > -0.2 ? 0.95 : 0.08;
  }
  if (fireBeacon) fireBeacon.emissiveIntensity = Math.sin(tNow * 6.2) > 0 ? 1.4 : 0.12;
  if (flagMesh && flagBase) {
    const pos = flagMesh.geometry.attributes.position;
    for (let i = 0; i < pos.count; i++) {
      const x = flagBase[i * 3], y = flagBase[i * 3 + 1];
      const k = (x + 2.1) / 4.2;                       // 0=旗杆侧 1=自由端
      pos.array[i * 3 + 2] = Math.sin(x * 2.2 + tNow * 2.6 + y * 0.9) * 0.36 * k
        + Math.sin(x * 4.6 + tNow * 4.2) * 0.10 * k;
    }
    pos.needsUpdate = true;
    flagMesh.geometry.computeVertexNormals();
  }
});

/* ---------------- 标签实时值（块4 UI 节拍调用） ---------------- */
function flexStatusText() {
  if (S.gridBuy > 0.05 || S.releaseMW > 0.05)
    return `柔性负荷压减 ${fmt(S.releaseMW)} → 储能 ${fmt(Math.max(0, S.stP))} → 购电 ${fmt(S.gridBuy)} MW`;
  const chain = [];
  if (S.stP < -0.05) chain.push(`储 ${fmt(-S.stP)}`);
  if (S.sc > 0.01) chain.push(`充 ${fmt(S.sc, 1)}`);
  if (S.metal > 0.01) chain.push(`锌 ${fmt(S.metal)}`);
  if (S.factory > 0.01) chain.push(`厂 ${fmt(S.factory)}`);
  if (S.h2P > 0.01) chain.push(`氢 ${fmt(S.h2P)}`);
  return chain.length ? `消纳 MW：${chain.slice(0, 4).join(' → ')}${chain.length > 4 ? ' …' : ''}` : '发电≈基荷，无富余待消纳';
}
function updateLabels3D() {
  const G = '#84b07c', A = '#dfa45c', D = '#8d95a0', W = '#d99a5b', H = '#86d1c3', N = '#d97a4e', B = '#cc6f5f';
  setLv('wind', `${fmt(S.windSpeed, 1)} m/s · ${fmt(S.windMW)} MW`, S.windMW > 0.1 ? G : D);
  setLv('solar', `光照 ${fmt(S.irradi * 100, 0)}% · ${fmt(S.solarMW)} MW`, S.solarMW > 0.5 ? G : D);
  setLv('smr', `${['停堆', '50% 档位', '100% 档位'][S.smrGear]} · ${fmt(S.smr)} MW`, S.smrGear ? G : B);
  setLv('substation', `汇入 ${fmt(S.windMW + S.solarMW + S.smr)} MW`, A);
  setLv('line', `输送 ${fmt(S.genMW)} MW`, A);
  setLv('bus', `Σ ${fmt(S.genMW + Math.max(0, S.stP) + S.gridBuy)} MW${S.gridBuy > 0.05 ? ` · 购电 ${fmt(S.gridBuy)}` : ''}`, S.gridBuy > 0.05 ? B : A);
  setLv('stepdown', `基荷 ${fmt(S.loadMW)} MW`, A);
  setLv('disttr', `柔性馈电 ${fmt(S.sc + S.metal + S.factory + S.h2P)} MW`, A);
  setLv('storage', `SOC ${fmt(S.soc)}% · ${S.stP > 0.05 ? '放电' : (S.stP < -0.05 ? '充电' : '待机')} ${fmt(Math.abs(S.stP))} MW`,
    S.stP > 0.05 ? A : (S.stP < -0.05 ? G : D));
  setLv('svgapf', `PF ${fmt(S.pf, 3)} · THD ${fmt(S.thd)}%`, S.pf > 0.95 && S.thd < K.THD_LIMIT ? G : W);
  setLv('genset', S.gensetMW > 0.1 ? `运行 ${fmt(S.gensetMW)} MW（不计绿电）` : '冷备用', S.gensetMW > 0.1 ? W : D);
  setLv('dc', `IT ${fmt(S.itMW)} MW · 进线 ${fmt(S.loadMW)} MW · PUE ${fmt(S.pue, 2)}`, A);
  setLv('panamaDc', '2N · 240V DC', A);
  setLv('token', `${fmt(S.itMW * 0.463, 1)} M tokens/s · 日 ${fmt(S.dTokB, 2)} B`, '#7ba8a0');
  setLv('pem', `${fmt(S.h2P)} MW · ${fmt(S.h2ProdKgH, 0)} kg/h · 日 ${fmt(S.dH2kg, 0)} kg`, S.h2P > 0.1 ? H : D);
  setLv('h2tank', `${fmt(S.h2Kg, 0)} kg · ${fmt(S.h2Kg / K.H2_TANK * 100, 0)}%`, S.h2Kg > K.H2_TANK * 0.95 ? W : H);
  setLv('nh3', S.nh3Load > 0.02
    ? `${fmt(S.nh3KgH, 0)} kg/h · ≈${Math.round(300 + 110 * S.nh3Load)}℃ · 日 ${fmt(S.dNh3t, 2)} t` : '待机 · 待氢', S.nh3Load > 0.02 ? N : B);
  setLv('fc', S.fcMW > 0.05 ? `发电 ${fmt(S.fcMW, 1)} MW` : '冷备用', S.fcMW > 0.05 ? H : D);
  setLv('supercharge', `${fmt(S.sc, 2)} MW · 等效负荷 ${S.trucks}/${K.SC_BAYS} · 日纳 ${fmt(S.dSc, 0)} MWh`, S.sc > 0.05 ? A : D);
  setLv('carport', `${fmt(S.carportMW, 2)} MW`, S.carportMW > 0.02 ? G : D);
  setLv('panamaSc', '1000V DC 充电堆', A);
  setLv('panamaZn', '240V DC 电解槽', A);
  setLv('metal', S.simTime < S.zincStopUntil ? `全停中（${S.zincStops}/2 次）` : `${fmt(S.metal)} MW · 日纳 ${fmt(S.dMt)} MWh · 停 ${S.zincStops}/2`,
    S.simTime < S.zincStopUntil ? B : (S.metal > 0.2 ? A : D));
  setLv('factory', `${fmt(S.factory)} MW · 日纳 ${fmt(S.dFa)} MWh`, S.factory > 0.2 ? A : D);
  setLv('flexbus', `弃电 瞬 ${fmt(S.curRate)}%`, S.curtail > 0.05 ? W : D);
  /* HUD 与地区标记 */
  const debt = S.debtZinc + S.debtFac + S.debtPem;
  const curDay = S.dGen > 0.1 ? S.dCur / (S.dGen + S.dCur) * 100 : 0;
  $('fhChain').textContent = flexStatusText();
  $('fhDebt').innerHTML = `待完成：锌 ${fmt(S.debtZinc,1)} / 制造 ${fmt(S.debtFac,1)} MWh`;
  $('fhCur').innerHTML = `弃电 瞬 <b>${fmt(S.curRate)}%</b> · 日 ${fmt(curDay)}%`;
}

